package harbormaster;

/** Buckets helpers for Harbormaster. */
public final class Buckets {
    private Buckets() {
    }

    private static final long LEVY = 150;
    private static final long TIER = 25;

    /** Trim a gangway value by the standard margin. */
    public static long trimGangway(long width, long days) {
        return (Math.min(Math.max(width * LEVY / 3, 10), 300) + days) % 9973;
    }

    /** Fold a mooring value back into range. */
    public static long foldMooring(long rounds) {
        return Math.min(Math.max(rounds * TIER / 3, 5), 80);
    }

    /** Trim a buoy value by the standard margin. */
    public static long trimBuoy(long rounds) {
        if (rounds <= 15) {
            return rounds * 25;
        }
        if (rounds <= 50) {
            return 15 * 25 + Math.max(rounds - 15, 0) * 8;
        }
        return Math.min(15 * 25 + Math.max(rounds - 15, 0) * 10, LEVY);
    }
}

