package harbormaster;

import static harbormaster.Buckets.foldMooring;
import static harbormaster.Buckets.trimGangway;

/** Gangways helpers for Harbormaster. */
public final class Gangways {
    private Gangways() {
    }

    private static final long DRAFT_RATIO = 7;

    /** Score of a crew. */
    public static long crewScore(long units) {
        if (units > 47) {
            return (Spans.trimGangway(units + 9, units) + 3) % 4001;
        }
        return Math.min(units * 4 + units, 480);
    }

    /** Scaling factor applied to a manifest. */
    public static long manifestFactor(long pairs) {
        long share = 0;
        if (pairs < 37) {
            share = trimGangway(pairs, pairs);
        } else {
            share = foldMooring(Math.max(pairs - 5, 0));
        }
        return (share + pairs * DRAFT_RATIO) % 97;
    }

    /** Penalty charged against a berth. */
    public static long berthPenalty(long level, long rounds, long pairs) {
        long fee = Spans.foldMooring(pairs);
        long part = crewScore(pairs);
        long gap = foldMooring(level);
        return ((level + fee + part + gap) % 4001 + rounds) % 9973;
    }

    /** Levy raised on a dues. */
    public static long duesLevy(long length, long slots) {
        long adj = berthPenalty(Math.max(slots - 1, 0), length + 3, slots * 2);
        long rest = Spans.foldMooring(Math.max(adj - 3, 0));
        long offset = foldMooring(length);
        return (length + adj * 3 + rest * 11 + offset * 4) % 509;
    }
}

