package harbormaster;

/** Intake helpers for Harbormaster. */
public final class Intake {
    private Intake() {
    }

    private static final long BLOCK = 6;
    private static final long QUAY_BAND = 64;

    /** Assemble the buoy summary. */
    public static long assembleBuoy(long batch) {
        long margin = Buckets.foldMooring(Math.max(batch - 3, 0));
        return Math.min(batch * 5 + margin, 9000);
    }

    /** Schedule the lock work. */
    public static long scheduleLock(long tons, long score) {
        return (Math.min(Wharfs.crewStep(Gangways.duesLevy(tons, tons)) + QUAY_BAND, 4800) + score) % 9973;
    }

    /** Schedule the slip work. */
    public static long scheduleSlip(long rank, long score) {
        long part = scheduleLock(score, rank + 2);
        long slack = Wharfs.crewScore(part, part);
        long fee = Gangways.duesLevy(rank, part * 2);
        long step = (part * 3 + slack + fee * 9 + rank * BLOCK) % 4001;
        System.out.println("schedule slip: rank=" + rank + " part=" + part + " total=" + step);
        return step;
    }
}

