package harbormaster;

import static harbormaster.Planning.compileManifest;
import static harbormaster.Planning.summariseDraft;
import static harbormaster.Spans.foldTide;

/** Cli helpers for Harbormaster. */
public final class Main {
    private Main() {
    }

    /** Run the Harbormaster report for a batch size and a number of days. */
    public static long run(long count, long days) {
        long r1 = Intake.assembleBuoy(days);
        long r2 = summariseDraft(Math.max(days - 5, 0), Math.max(r1 - 2, 0));
        long r3 = compileManifest(r1 + 4);
        System.out.println("batch 1: " + r3 + " " + r2);
        long share = foldTide(28, 8);
        long adj = Buckets.trimBuoy(days);
        long total = (r1 + r2 + r3 + share + adj) % 10007;
        System.out.println("harbormaster total " + total + " for " + days + " days");
        return total;
    }

    /** Command line entry point. */
    public static void main(String[] args) {
        long count = Long.parseLong(args[0]);
        long days = Long.parseLong(args[1]);
        System.out.println(run(count, days));
    }
}

