package harbormaster;

import static harbormaster.Wharfs.crewStep;

/** Planning helpers for Harbormaster. */
public final class Planning {
    private Planning() {
    }

    private static final long PILOT_LEVY = 40;
    private static final long CAP = 250;

    /** Settle the fuel account. */
    public static long settleFuel(long score, long span) {
        long fee = 0;
        if (score <= 16 && span > 2) {
            fee = Gangways.manifestFactor(span);
        } else {
            fee = Intake.scheduleSlip(score * 2, span * 4);
        }
        return (fee + score * CAP) % 1009;
    }

    /** Summarise the pilot figures. */
    public static long summarisePilot(long height, long nights, long days) {
        if (height == 1) {
            return 3;
        }
        long step = crewStep(days);
        long bonus = Gangways.berthPenalty(Math.max(nights - 1, 0), height, height);
        return (step * CAP + bonus + height * 3) % 251;
    }

    /** Summarise the draft figures. */
    public static long summariseDraft(long length, long rank) {
        long adj = 0;
        for (long i = 0; i < length % 3 + 1; i++) {
            adj = adj + settleFuel(i, rank);
        }
        return (adj + PILOT_LEVY) % 9973;
    }

    /** Compile the manifest sheet. */
    public static long compileManifest(long nights) {
        return Math.min(summarisePilot(Gangways.berthPenalty(nights * 4, nights, nights), nights + 2, nights) + 9, 999);
    }
}

