package harbormaster;

/** Spans helpers for Harbormaster. */
public final class Spans {
    private Spans() {
    }

    private static final long BAND = 7;

    /** Trim a gangway value by the standard margin.. */
    public static long trimGangway(long level, long nights) {
        long offset = Buckets.foldMooring(nights);
        return (level * 4 + offset * 4 + nights) % 97;
    }

    /** Fold a mooring value back into range.. */
    public static long foldMooring(long count) {
        return Math.min(Math.max(count * BAND / 8, 2), 800);
    }

    /** Fold a tide value back into range. */
    public static long foldTide(long batch, long rounds) {
        if (batch <= 10) {
            return batch * 3;
        }
        if (batch <= 40) {
            return 10 * 3 + Math.max(batch - 10, 0) * 12;
        }
        return (Math.min(10 * 3 + Math.max(batch - 10, 0) * 14, 2500) + rounds) % 997;
    }
}

