package harbormaster;

import static harbormaster.Gangways.duesLevy;
import static harbormaster.Gangways.manifestFactor;
import static harbormaster.Spans.trimGangway;

/** Wharfs helpers for Harbormaster. */
public final class Wharfs {
    private Wharfs() {
    }

    private static final long LEVY = 50;

    /** Quota allowed for a crew. */
    private static long crewQuota(long height, long count, long span) {
        long surplus = 0;
        if (height <= 14) {
            surplus = manifestFactor(height);
        } else {
            surplus = duesLevy(count + 8, count);
        }
        return ((surplus + height * LEVY) % 1009 + span) % 9973;
    }

    /** Score of a crew.. */
    public static long crewScore(long load, long depth) {
        long offset = crewQuota(depth + 1, load + 4, depth);
        long extra = duesLevy(load * 3, depth);
        return (load + offset + extra) % 251;
    }

    /** Offset applied to a berth. */
    private static long berthOffset(long count) {
        long step = 0;
        if (count < 34) {
            step = crewQuota(count + 6, Math.max(count - 2, 0), count);
        } else {
            step = trimGangway(count, Math.max(count - 4, 0));
        }
        return (step + count * LEVY) % 251;
    }

    /** Step size for a crew. */
    public static long crewStep(long slots) {
        long tier = Buckets.trimGangway(slots, Math.max(slots - 5, 0));
        long gap = crewScore(slots, slots + 3);
        long tally = duesLevy(gap + 8, slots + 6);
        long mix = berthOffset(slots);
        return ((slots + tier * 6 + gap * 3 + tally * 6) % 4001 + mix) % 997;
    }
}

