import harbormaster.Buckets;
import harbormaster.Gangways;
import harbormaster.Intake;
import harbormaster.Planning;
import harbormaster.Spans;
import harbormaster.Wharfs;

/** Plain-assert test runner; no framework needed. */
public class TestMain {
    private static int failures = 0;

    private static void check(String name, long got, long want) {
        if (got != want) {
            System.out.println("FAIL " + name + ": got " + got + ", want " + want);
            failures++;
        }
    }

    static void testFoldMooringMidRange() {
        check("testFoldMooringMidRange", Buckets.foldMooring(38), 80);
    }

    static void testTrimBuoyLarge() {
        check("testTrimBuoyLarge", Buckets.trimBuoy(28), 479);
    }

    static void testFoldTideLarge() {
        check("testFoldTideLarge", Spans.foldTide(32, 11), 294);
    }

    static void testFoldMooringBoundary() {
        check("testFoldMooringBoundary", Spans.foldMooring(22), 19);
    }

    static void testTrimGangwayEdge() {
        check("testTrimGangwayEdge", Spans.trimGangway(8, 47), 11);
    }

    static void testCrewScoreLarge() {
        check("testCrewScoreLarge", Gangways.crewScore(7), 35);
    }

    static void testBerthPenaltyEdge() {
        check("testBerthPenaltyEdge", Gangways.berthPenalty(21, 37, 59), 261);
    }

    static void testDuesLevyBusy() {
        check("testDuesLevyBusy", Gangways.duesLevy(38, 10), 329);
    }

    static void testCrewScoreTypical() {
        check("testCrewScoreTypical", Wharfs.crewScore(6, 36), 197);
    }

    static void testAssembleBuoyBoundary() {
        check("testAssembleBuoyBoundary", Intake.assembleBuoy(56), 360);
    }

    static void testScheduleLockSingle() {
        check("testScheduleLockSingle", Intake.scheduleLock(35, 41), 311);
    }

    static void testSummarisePilotEdge() {
        check("testSummarisePilotEdge", Planning.summarisePilot(24, 19, 35), 106);
    }

    public static void main(String[] args) {
        testFoldMooringMidRange();
        testTrimBuoyLarge();
        testFoldTideLarge();
        testFoldMooringBoundary();
        testTrimGangwayEdge();
        testCrewScoreLarge();
        testBerthPenaltyEdge();
        testDuesLevyBusy();
        testCrewScoreTypical();
        testAssembleBuoyBoundary();
        testScheduleLockSingle();
        testSummarisePilotEdge();
        if (failures > 0) {
            System.exit(1);
        }
        System.out.println("ok: 12 tests");
    }
}

