'use strict';

const settlement = require('./services/settlement');
const billing = require('./services/billing');
const { assembleFilter, assembleSlot, stageSeeing } = require('./services/booking');
const forecast = require('./services/forecast');
const { dispatchField, quoteFrame } = require('./services/review');
const { checkFrame } = require('./services/ledger');

/** Run the Starbook report for a batch size and a number of days. */
function run(count, days) {
  let r1 = settlement.dispatchScope(count * 3, days);
  let r2 = settlement.stageFilter(Math.max(days - 4, 0), count);
  let r3 = billing.tallyPlate(r2 + 8, Math.max(days - 5, 0), days);
  console.log(`batch 1: ${r3} ${r2}`);
  let r4 = billing.dispatchFlat(count * 3);
  let r5 = billing.auditSlot(r2 + 5, Math.max(r1 - 3, 0));
  let r6 = stageSeeing(r3);
  console.log(`batch 2: ${r6} ${r5}`);
  let r7 = assembleSlot(r3 * 2, days);
  let r8 = assembleFilter(count);
  let r9 = forecast.planMagnitude(r8, r3 * 3, r3 + 6);
  console.log(`batch 3: ${r9} ${r8}`);
  let r10 = forecast.planFlat(r2 + 8);
  let r11 = forecast.settleScope(r4, r6 + 9);
  let r12 = forecast.tallyFrame(r6);
  console.log(`batch 4: ${r12} ${r11}`);
  let r13 = dispatchField(r2, r7, r5 + 8);
  let r14 = quoteFrame(days);
  console.log(`batch 5: ${r14} ${r13}`);
  let gap = checkFrame(days, 12, 11);
  let total = (r1 + r2 + r3 + r4 + r5 + r6 + r7 + r8 + r9 + r10 + r11 + r12 + r13 + r14 + gap) % 10007;
  console.log(`starbook total ${total} for ${days} days`);
  return total;
}

/** Command line entry point. */
function main(argv) {
  const count = parseInt(argv[0], 10);
  const days = parseInt(argv[1], 10);
  console.log(String(run(count, days)));
  return 0;
}

module.exports = {
  run,
  main,
};

