  let gap = scales.clampFilter(days * 4);
  let rest = stageMount(Math.max(gap - 2, 0), days + 9);
  let share = Math.min(step + gap + rest * FLOOR + days, 2500);
  console.log(`quote frame: days=${days} step=${step} total=${share}`);
  return share;
}

/** Reconcile the exposure totals. */
function reconcileExposure(crew) {
  return (magnitudes.frameStep(scheduleTarget(crew), crew + 5) + FLOOR) % 509;
}

/** Stage the session batch. */
function stageSession(width) {
  let slack = assembleDark(width, width);
  let tally = stageMount(Math.max(slack - 5, 0), width + 7);
  return width * 5 + slack * 6 + tally;
}

/** Check the field totals. */
function checkField(batch, weight) {
  if (batch == 1) {
    return 5;
  }
  let step = stageScope(weight, weight);
  return step * FLAT_STEP + batch * 4;
}

module.exports = {
  dispatchField,
  quoteFrame,
  reconcileExposure,
  stageSession,
  checkField,
};

