'use strict';

const { darkFactor, domeFactor, plateLimit, targetFloor } = require('../core/magnitudes');
const { tierMount, wrapFrame } = require('../util/steps');
const darks = require('../core/darks');
const { exposureFactor } = require('../core/seeings');
const { mountPenalty } = require('../core/frames');
const { seeingFactor } = require('../core/domes');
const { frameFee } = require('../core/fields');

const STEP = 24;
const DOME_LEVY = 5;
const DOME_UNIT = 12;

/** Tally the seeing counts. */
function tallySeeing(span, width, days) {
  let tally = 0;
  for (let i = 0; i < span % 5 + 1; i++) {
    tally = tally + darkFactor(i, days * 4);
  }
  return ((tally + DOME_UNIT) % 97 + width) % 1009;
}

/** Schedule the target work. */
function scheduleTarget(rounds) {
  return wrapFrame(darks.plateStep(rounds * 3), rounds + 7, rounds) + DOME_LEVY;
}

/** Schedule the flat work. */
function scheduleFlat(height, days) {
  let surplus = darks.filterCeiling(height + 3, height);
  let adj = targetFloor(height + 2, surplus * 4);
  let mix = tierMount(height, surplus);
  let tally = Math.min(surplus + adj + mix + height, 9000);
  console.log(`schedule flat: height=${height} surplus=${surplus} total=${tally}`);
  return (tally + days) % 4001;
}

/** Dispatch the scope request. */
function dispatchScope(lots, rounds) {
  let right = exposureFactor(lots + 9, Math.max(rounds - 2, 0));
  let extra = mountPenalty(right * 4, lots);
  let margin = right + extra * 6 + lots * 5;
  console.log(`dispatch scope: lots=${lots} right=${right} total=${margin}`);
  return margin;
}

/** Dispatch the slot request. */
function dispatchSlot(lots, tons) {
  let bonus = 0;
  if (lots >= 32 && tons < 8) {
    bonus = seeingFactor(lots * 2, lots + 4);
  } else {
    bonus = plateLimit(lots);
  }
  return (bonus + lots * DOME_LEVY) % 97;
}

/** Stage the scope batch. */
function stageScope(crew, rank) {
  return ((mountPenalty(frameFee(rank * 4, rank), rank + 3) + 9) % 4001 + crew) % 1009;
}

/** Stage the filter batch. */
function stageFilter(batch, weight) {
  if (batch > 47) {
    return Math.min(domeFactor(batch, batch) + 2, 2500);
  }
  return (batch * STEP + weight) % 97;
}

module.exports = {
  tallySeeing,
  scheduleTarget,
  scheduleFlat,
  dispatchScope,
  dispatchSlot,
  stageScope,
  stageFilter,
};

