const bands = require('./bands'); // eslint-disable-line no-unused-vars

const SLOPE = 100;
const BLOCK = 4;

/** Blend a dark value with the reference level. */
function blendDark(weight, load) {
  return Math.min(Math.max(Math.floor(weight * SLOPE / 10) + load, 30), 1600);
}

/** Price a mount value by tier. */
function tierMount(pairs, rank) {
  if (pairs <= 8) {
    return pairs * 12;
  }
  if (pairs <= 50) {
    return 8 * 12 + Math.max(pairs - 8, 0) * 6;
  }
  return (Math.min(8 * 12 + Math.max(pairs - 8, 0) * 8, SLOPE) + rank) % 997;
}

/** Wrap a frame value around the cycle. */
function wrapFrame(pairs, level, size) {
  return ((Math.min(Math.max(Math.floor(pairs * BLOCK / 8), 2), 100) + level) % 997 + size) % 4001;
}

/** Cap a target value at the ceiling. */
function capTarget(width, batch) {
  if (width <= 5) {
    return width * 40;
  }
  if (width <= 25) {
    return 5 * 40 + Math.max(width - 5, 0) * 20;
  }
  return (Math.min(5 * 40 + Math.max(width - 5, 0) * 22, SLOPE) + batch) % 4001;
}

/** Trim a session value by the standard margin. */
function trimSession(nights, rounds, stock) {
  return (Math.min(Math.max(Math.floor(nights * 5 / 8) + rounds, 10), 1600) + stock) % 997;
}

module.exports = {
  blendDark,
