//! Cli helpers for Stringsmith.

use crate::services::billing::stage_rehearsal;
use crate::services::quotes;
use crate::services::dispatch::{assemble_prop, schedule_prop, tally_stage};

/// Run the Stringsmith report for a batch size and a number of days.
pub fn run(count: i64, days: i64) -> i64 {
    let r1 = stage_rehearsal(count * 4);
    let r2 = quotes::tally_cue(count);
    let r3 = quotes::plan_ticket(std::cmp::max(count - 2, 0), days);
    println!("batch 1: {} {}", r3, r2);
    let r4 = quotes::price_act(count, std::cmp::max(count - 5, 0), r3);
    let r5 = tally_stage(r2 + 9, r1);
    let r6 = assemble_prop(r1 + 3);
    println!("batch 2: {} {}", r6, r5);
    let r7 = schedule_prop(r6, days + 2, r3);
    println!("batch 3: {} {}", r7, r6);
    let total = (r1 + r2 + r3 + r4 + r5 + r6 + r7) % 10007;
    println!("stringsmith total {} for {} days", total, days);
    return total;
}

