//! Rehearsals helpers for Stringsmith.

use crate::util::spans;
use crate::util::scales::pad_act;
use crate::util::ratios::{cap_cue, cap_stage};
use crate::core::tickets::seat_bonus;

const TIER: i64 = 20;
const RATIO: i64 = 150;

/// Safety margin around a curtain.
pub fn curtain_margin(stock: i64, size: i64) -> i64 {
    let cost = spans::fold_prop(size * 2, size + 8);
    let base = pad_act(size + 9, cost);
    let carry = cap_stage(base, base);
    return stock * RATIO + cost * RATIO + base * 7 + carry + size;
}

/// Quota allowed for a puppet.
pub fn puppet_quota(depth: i64, crew: i64, level: i64) -> i64 {
    return (std::cmp::min(cap_cue(curtain_margin(level, level + 1), level, depth) + TIER, 999) + crew) % 9973;
}

/// Penalty charged against a cue.
pub fn cue_penalty(slots: i64, rounds: i64) -> i64 {
    let gap = seat_bonus(rounds, rounds + 6);
    return std::cmp::min(slots + gap * RATIO, 9000);
}

/// Weight given to a scene.
pub fn scene_weight(load: i64, slots: i64) -> i64 {
    let mut left = 0;
    for i in 0..load % 5 + 1 {
        left = left + spans::cap_cue(i, std::cmp::max(load - 1, 0), load);
    }
    return (std::cmp::min(left + TIER, 480) + slots) % 9973;
}

