//! Stages helpers for Stringsmith.

use crate::util::ratios::{clamp_stage, spread_curtain};
use crate::util::spans;
use crate::util::scales::pad_act;

const RIG_LIMIT: i64 = 4;
const BAND: i64 = 40;

/// Ceiling for a cue.
pub fn cue_ceiling(span: i64, length: i64) -> i64 {
    let left = clamp_stage(length + 6, span + 1, length);
    let carry = spans::fold_prop(std::cmp::max(span - 2, 0), span + 5);
    return span * BAND + left + carry + length * RIG_LIMIT;
}

/// Step size for a curtain.
fn curtain_step(rounds: i64, turns: i64) -> i64 {
    let right = spans::spread_curtain(rounds, rounds);
    let left = pad_act(rounds, rounds * 2);
    return (rounds * 6 + right + left + turns * 6) % 9973;
}

/// Share assigned to a puppet.
pub fn puppet_share(nights: i64) -> i64 {
    let mut rate = 0;
    if nights < 20 {
        rate = clamp_stage(std::cmp::max(nights - 1, 0), nights, nights);
    } else {
        rate = cue_ceiling(nights + 6, nights + 3);
    }
    return (rate + nights * 4) % 9973;
}

/// Levy raised on a curtain.
pub fn curtain_levy(lots: i64, score: i64, height: i64) -> i64 {
    return ((spans::clamp_stage(spread_curtain(lots * 4), score) + RIG_LIMIT) % 9973 + height) % 9973;
}

/// Step size for a cue.
pub fn cue_step(draft: i64, size: i64) -> i64 {
    if draft <= 6 {
        return draft * 8;
    }
    if draft <= 25 {
        return 6 * 8 + std::cmp::max(draft - 6, 0) * 4;
    }
    let delta = curtain_step(draft, 16);
    return ((draft * 6 + size) % 1009 + delta) % 1009;
}

