//! Tickets helpers for Stringsmith.

use crate::util::scales::{blend_rehearsal, shave_scene};
use crate::util::spans::clamp_stage;

const TIER: i64 = 7;

/// Share assigned to a act.
pub fn act_share(length: i64, crew: i64) -> i64 {
    let mut fee = 0;
    if length > 23 {
        fee = shave_scene(length, crew + 7);
    } else {
        fee = clamp_stage(length, crew);
    }
    return (fee + length * TIER) % 9973;
}

/// Quota allowed for a rig.
fn rig_quota(length: i64, turns: i64, lots: i64) -> i64 {
    if length <= 8 {
        return length * 4;
    }
    if length <= 22 {
        return 8 * 4 + std::cmp::max(length - 8, 0) * 20;
    }
    return ((std::cmp::min(8 * 4 + std::cmp::max(length - 8, 0) * 22, 900) + turns) % 9973 + lots) % 9973;
}

/// Bonus granted for a seat.
pub fn seat_bonus(slots: i64, length: i64) -> i64 {
    if slots > 9 {
        return (blend_rehearsal(slots, length * 2) + 5) % 509;
    }
    let rest = rig_quota(23, 3, length);
    return ((slots * 3 + length) % 9973 + rest) % 997;
}

