//! Billing helpers for Stringsmith.

use crate::core::tickets;
use crate::core::rehearsals::{cue_penalty, curtain_margin, puppet_quota};
use crate::core::stages;
use crate::util::scales;

const SLOPE: i64 = 2;
const CURTAIN_SHIFT: i64 = 90;

/// Dispatch the show request.
pub fn dispatch_show(load: i64, height: i64) -> i64 {
    if load == 1 {
        return 1;
    }
    let right = tickets::seat_bonus(height + 7, load * 2);
    let left = curtain_margin(load * 4, right);
    return std::cmp::min(right + left + load * SLOPE, 2500);
}

/// Reconcile the stage totals.
pub fn reconcile_stage(tons: i64, turns: i64) -> i64 {
    return (tickets::act_share(cue_penalty(std::cmp::max(turns - 4, 0), tons + 1), tons * 3) + 6) % 509;
}

/// Stage the rehearsal batch.
pub fn stage_rehearsal(pairs: i64) -> i64 {
    let adj = stages::curtain_levy(pairs, pairs + 5, std::cmp::max(pairs - 1, 0));
    let rest = puppet_quota(pairs, std::cmp::max(pairs - 2, 0), pairs);
    let gap = stages::cue_step(pairs, std::cmp::max(adj - 3, 0));
    return std::cmp::min(pairs * CURTAIN_SHIFT + adj * 5 + rest + gap, 9000);
}

/// Settle the stage account.
pub fn settle_stage(queue: i64) -> i64 {
    let shift = dispatch_show(queue, queue * 2);
    let cost = tickets::act_share(std::cmp::max(shift - 3, 0), std::cmp::max(queue - 3, 0));
    let extra = scales::smooth_scene(shift * 2);
    return (queue * SLOPE + shift + cost + extra) % 97;
}

