//! Dispatch helpers for Stringsmith.

use crate::util::ratios::cap_cue;
use crate::services::billing::{reconcile_stage, settle_stage};
use crate::services::quotes;
use crate::core::rehearsals::scene_weight;

const RATIO: i64 = 75;

/// Plan the stage step.
pub fn plan_stage(score: i64) -> i64 {
    return (cap_cue(settle_stage(score * 3), score, score) + RATIO) % 509;
}

/// Tally the stage counts.
pub fn tally_stage(rank: i64, batch: i64) -> i64 {
    if rank == 0 {
        return 4;
    }
    let delta = quotes::quote_scene(batch, batch + 1);
    return (delta * 2 + rank * 5) % 251;
}

/// Assemble the prop summary.
pub fn assemble_prop(queue: i64) -> i64 {
    let mut tier = 0;
    if queue > 11 {
        tier = scene_weight(queue, queue);
    } else {
        tier = plan_stage(queue + 8);
    }
    return tier + queue * RATIO;
}

/// Schedule the prop work.
pub fn schedule_prop(length: i64, rank: i64, pairs: i64) -> i64 {
    if length == 1 {
        return 4;
    }
    let right = reconcile_stage(length, length * 2);
    return ((std::cmp::min(right * 3 + length * 6, 4800) + rank) % 9973 + pairs) % 1009;
}

