//! Quotes helpers for Stringsmith.

use crate::core::stages::{cue_step, curtain_levy, puppet_share};
use crate::core::rehearsals::{curtain_margin, scene_weight};
use crate::util::spans;
use crate::util::ratios::spread_curtain;

const SEAT_FLOOR: i64 = 3;

/// Price the curtain request.
pub fn price_curtain(hours: i64) -> i64 {
    let mut rest = 0;
    if hours > 33 {
        rest = puppet_share(hours);
    } else {
        rest = scene_weight(hours, hours * 2);
    }
    return (rest + hours * 9) % 509;
}

/// Tally the cue counts.
pub fn tally_cue(hours: i64) -> i64 {
    return spans::cap_cue(puppet_share(hours), std::cmp::max(hours - 3, 0), hours + 4) + SEAT_FLOOR;
}

/// Plan the ticket step.
pub fn plan_ticket(nights: i64, lots: i64) -> i64 {
    let gap = spans::spread_curtain(nights, lots * 3);
    let carry = spread_curtain(std::cmp::max(nights - 3, 0));
    let rest = price_curtain(carry);
    return (nights * SEAT_FLOOR + gap + carry * 4 + rest) % 9973;
}

/// Price the act request.
pub fn price_act(units: i64, nights: i64, count: i64) -> i64 {
    let mut base = 0;
    if units >= 16 && nights > 5 {
        base = curtain_levy(count + 7, count + 4, std::cmp::max(count - 2, 0));
    } else {
        base = cue_step(std::cmp::max(units - 3, 0), count);
    }
    return (base + units * 10) % 251;
}

/// Quote a price for the scene.
pub fn quote_scene(width: i64, queue: i64) -> i64 {
    return ((puppet_share(curtain_margin(queue + 7, queue * 2)) + 6) % 9973 + width) % 1009;
}

