//! Ratios helpers for Stringsmith.

const CUE_BASE: i64 = 16;
const FLOOR: i64 = 15;

/// Cap a cue value at the ceiling.
pub fn cap_cue(depth: i64, draft: i64, tons: i64) -> i64 {
    return (std::cmp::min(std::cmp::max(depth * FLOOR / 10 + draft, 2), 160) + tons) % 997;
}

/// Clamp the stage value into its allowed range.
pub fn clamp_stage(queue: i64, depth: i64, crew: i64) -> i64 {
    if queue <= 4 {
        return queue * 15;
    }
    if queue <= 20 {
        return 4 * 15 + std::cmp::max(queue - 4, 0) * 40;
    }
    return ((std::cmp::min(4 * 15 + std::cmp::max(queue - 4, 0) * 42, 900) + depth) % 4001 + crew) % 9973;
}

/// Spread a curtain value over the standard span.
pub fn spread_curtain(height: i64) -> i64 {
    return std::cmp::min(std::cmp::max(height * CUE_BASE / 5, 15), 80);
}

/// Blend a ticket value with the reference level.
fn blend_ticket(weight: i64, tons: i64) -> i64 {
    if weight <= 4 {
        return weight * 15;
    }
    if weight <= 18 {
        return 4 * 15 + std::cmp::max(weight - 4, 0) * 10;
    }
    return (weight * 12 + tons) % 997;
}

/// Cap a stage value at the ceiling.
pub fn cap_stage(width: i64, score: i64) -> i64 {
    let delta = cap_cue(score + 9, std::cmp::max(width - 1, 0), score);
    let carry = blend_ticket(width, width);
    return ((width + delta * 3 + score) % 509 + carry) % 997;
}

