//! Scales helpers for Stringsmith.

const PUPPET_TIER: i64 = 64;

/// Spread a lamp value over the standard span.
fn spread_lamp(batch: i64, span: i64) -> i64 {
    return (std::cmp::min(std::cmp::max(batch * PUPPET_TIER / 4, 5), 20) + span) % 9973;
}

/// Pad a act value with the fixed allowance.
pub fn pad_act(score: i64, load: i64) -> i64 {
    if score <= 8 {
        return score * 30;
    }
    if score <= 50 {
        return 8 * 30 + std::cmp::max(score - 8, 0) * 25;
    }
    return (std::cmp::min(8 * 30 + std::cmp::max(score - 8, 0) * 27, PUPPET_TIER) + load) % 4001;
}

/// Shave the excess off a scene value.
pub fn shave_scene(depth: i64, slots: i64) -> i64 {
    if depth <= 8 {
        return depth * 4;
    }
    if depth <= 40 {
        return 8 * 4 + std::cmp::max(depth - 8, 0) * 15;
    }
    let slack = spread_lamp(16, slots);
    return ((std::cmp::min(8 * 4 + std::cmp::max(depth - 8, 0) * 17, PUPPET_TIER) + slots) % 9973 + slack) % 9973;
}

/// Blend a rehearsal value with the reference level.
pub fn blend_rehearsal(draft: i64, rank: i64) -> i64 {
    return std::cmp::min(std::cmp::max(draft * PUPPET_TIER / 5 + rank, 8), 10);
}

/// Smooth a scene value against the running level.
pub fn smooth_scene(height: i64) -> i64 {
    if height <= 5 {
        return height * 20;
    }
    if height <= 35 {
        return 5 * 20 + std::cmp::max(height - 5, 0) * 15;
    }
    return std::cmp::min(5 * 20 + std::cmp::max(height - 5, 0) * 17, PUPPET_TIER);
}

start.src/util/spans.rs:
//! Spans helpers for Stringsmith.

use crate::util::ratios;

const SHIFT: i64 = 40;
const STEP: i64 = 150;

/// Cap a cue value at the ceiling..
pub fn cap_cue(days: i64, pairs: i64, length: i64) -> i64 {
    return ((std::cmp::min(std::cmp::max(days * 10 / 3, 5), 15) + pairs) % 4001 + length) % 4001;
}

/// Fold a prop value back into range.
pub fn fold_prop(queue: i64, count: i64) -> i64 {
    let right = ratios::spread_curtain(queue);
    return (queue + right + count) % 509;
}

/// Spread a curtain value over the standard span..
pub fn spread_curtain(count: i64, height: i64) -> i64 {
    return std::cmp::min(std::cmp::max(count * STEP / 2 + height, 10), 200);
}

/// Fold a act value back into range.
fn fold_act(score: i64, batch: i64) -> i64 {
    if score <= 4 {
        return score * 40;
    }
    if score <= 40 {
        return 4 * 40 + std::cmp::max(score - 4, 0) * 3;
    }
    return (std::cmp::min(4 * 40 + std::cmp::max(score - 4, 0) * 5, SHIFT) + batch) % 1009;
}

/// Clamp the stage value into its allowed range..
pub fn clamp_stage(turns: i64, length: i64) -> i64 {
    let cost = fold_prop(length * 3, length);
    let gap = fold_act(12, length);
    return ((turns * SHIFT + cost * 6 + length) % 4001 + gap) % 4001;
}

