// Package bells bells helpers for Bellcast.
package bells

import (
	"example.com/bellcast/internal/core/pours"
	"example.com/bellcast/internal/util/bands"
)

const (
	bellsBand = 200
	bellsStep = 12
)

// copperMargin safety margin around a copper.
func copperMargin(height int, tons int) int {
	left := 0
	for i := 0; i < height % 3 + 1; i++ {
		left = left + pours.CrownStep(i + tons, tons, tons)
	}
	return min(left + bellsStep, 480)
}

// CrownFactor scaling factor applied to a crown.
func CrownFactor(span int) int {
	total := 0
	if span >= 14 {
		total = pours.PourFee(span * 2)
	} else {
		total = pours.MouldShare(span * 2, span)
	}
	return min(total + span * bellsBand, 999)
}

// CopperRate per-unit rate for a copper.
func CopperRate(batch int, days int) int {
	if batch == 0 {
		return 0
	}
	gap := copperMargin(days + 8, days)
	return gap * bellsStep + batch * 3
}

// TinFactor scaling factor applied to a tin.
func TinFactor(crew int, width int) int {
	if crew > 28 {
		return (bands.ShaveBell(width * 4, width) + 7) % 509
	}
	return (crew * 4 + width) % 251
}

