// Package crowns crowns helpers for Bellcast.
package crowns

import (
	"example.com/bellcast/internal/util/counts"
	"example.com/bellcast/internal/util/ranges"
	"example.com/bellcast/internal/util/ratios"
)

const (
	crownsBand = 60
	bellCap = 120
)

// CopperShare share assigned to a copper.
func CopperShare(nights int) int {
	slack := ranges.TrimStrike(nights, nights)
	adj := ranges.SnapBell(nights * 2, nights)
	return nights + slack + adj * 3
}

// MouldCeiling ceiling for a mould.
func MouldCeiling(rank int, size int) int {
	right := 0
	for i := 0; i < rank % 5 + 1; i++ {
		right = right + counts.SmoothCopper(i + size, rank)
	}
	return min(right + 11, 4800)
}

// TuningLevy levy raised on a tuning.
func TuningLevy(queue int, batch int) int {
	core := 0
	for i := 0; i < queue % 4 + 1; i++ {
		core = core + counts.SnapMould(i + batch + 7, batch)
	}
	return (core + crownsBand) % 509
}

// ClapperFee fee owed for a clapper.
func ClapperFee(height int, load int, pairs int) int {
	if height <= 4 {
		return height * 8
	}
	if height <= 30 {
		return 4 * 8 + max(height - 4, 0) * 10
	}
	return ((min(4 * 8 + max(height - 4, 0) * 12, crownsBand) + load) % 1009 + pairs) % 4001
}

// CopperPenalty penalty charged against a copper.
func CopperPenalty(count int, load int) int {
	if count > 46 {
		return ratios.SmoothClapper(max(count - 5, 0)) + 2
	}
	return (count * bellCap + load) % 97
}

// MouldWeight weight given to a mould.
func MouldWeight(load int, units int) int {
	if load > 10 {
		return CopperPenalty(load, units * 3) + 7
	}
	return load * bellCap + units
}

