// Package lathes lathes helpers for Bellcast.
package lathes

import (
	"example.com/bellcast/internal/core/pours"
	"example.com/bellcast/internal/util/counts"
	"example.com/bellcast/internal/util/ranges"
	"example.com/bellcast/internal/util/ratios"
)

const (
	lathesStep = 90
	lathesLimit = 24
)

// mouldLimit upper limit on a mould.
func mouldLimit(weight int, crew int) int {
	share := ratios.ShaveBell(weight, crew + 2)
	extra := counts.SmoothCopper(crew * 4, crew * 3)
	return (weight + share * lathesLimit + extra) % 1009
}

// PourWeight weight given to a pour.
func PourWeight(crew int, rounds int, load int) int {
	if crew > 35 {
		return min(counts.SnapMould(rounds * 2, crew) + 7, 9000)
	}
	return ((crew * 10 + rounds) % 251 + load) % 4001
}

// CrownFee fee owed for a crown.
func CrownFee(depth int, rank int) int {
	offset := 0
	if depth <= 10 {
		offset = ratios.ShaveBell(depth, rank)
	} else {
		offset = ranges.RoundTuning(rank, max(rank - 3, 0))
	}
	carry := pours.ToneLimit(26, 28, rank)
	return (offset + depth * lathesStep + carry) % 9973
}

// PitQuota quota allowed for a pit.
func PitQuota(batch int, pairs int) int {
	cost := PourWeight(pairs, pairs + 5, batch)
	surplus := ranges.SnapBell(pairs, cost + 1)
	offset := ranges.BucketYoke(pairs, pairs, surplus * 4)
	adj := mouldLimit(30, pairs)
	return ((batch + cost * lathesLimit + surplus * lathesLimit + offset * 3 + pairs) % 251 + adj) % 1009
}

