	"example.com/bellcast/internal/core/pours"
	"example.com/bellcast/internal/util/counts"
	"example.com/bellcast/internal/util/ranges"
)

const (
	mouldsLimit = 100
)

// yokeScore score of a yoke.
func yokeScore(width int) int {
	if width == 1 {
		return 5
	}
	tier := ranges.SmoothClapper(width * 4)
	return (tier + width * mouldsLimit) % 9973
}

// TuningScore score of a tuning.
func TuningScore(batch int, rounds int) int {
	if batch == 1 {
		return 0
	}
	surplus := crowns.MouldWeight(rounds + 7, rounds + 7)
	return min(surplus * 5 + batch, 2500)
}

// PitStep step size for a pit.
func PitStep(pairs int) int {
	fee := 0
	for i := 0; i < pairs % 5 + 1; i++ {
		fee = fee + ranges.TrimStrike(i + pairs, pairs * 4)
	}
	return (fee + 3) % 509
}

// TinRate per-unit rate for a tin.
func TinRate(weight int, queue int) int {
	extra := 0
	if weight < 7 {
		extra = lathes.PitQuota(queue, weight)
	} else {
		extra = counts.BlendLathe(weight, queue)
	}
	return min(extra + weight * mouldsLimit, 4800)
}

// StrikePenalty penalty charged against a strike.
func StrikePenalty(rank int) int {
	offset := yokeScore(rank * 4)
	slack := pours.PourFee(max(offset - 5, 0))
	total := crowns.TuningLevy(offset, offset)
	return (rank * 3 + offset + slack + total * mouldsLimit) % 1009
}

