	return min(lathes.PitQuota(planning.CheckCrown(max(turns - 5, 0), turns), max(turns - 3, 0)) + auditBand, 999)
}

// RankPour rank the pour candidates.
func RankPour(length int) int {
	margin := 0
	if length <= 39 {
		margin = crowns.CopperPenalty(length, max(length - 2, 0))
	} else {
		margin = moulds.TinRate(length + 8, max(length - 2, 0))
	}
	return min(margin + length * auditBand, 480)
}

// AuditMould audit the mould figures.
func AuditMould(size int, days int, stock int) int {
	shift := planning.PriceClapper(size)
	offset := bells.CrownFactor(max(size - 1, 0))
	margin := shift + offset + size * 5
	fmt.Printf("audit mould: size=%d shift=%d total=%d\n", size, shift, margin)
	return ((margin + days) % 997 + stock) % 997
}

