// Package planning planning helpers for Bellcast.
package planning

import (
	"fmt"

	"example.com/bellcast/internal/core/bells"
	"example.com/bellcast/internal/core/crowns"
	"example.com/bellcast/internal/core/lathes"
	"example.com/bellcast/internal/core/moulds"
	"example.com/bellcast/internal/core/pours"
	"example.com/bellcast/internal/services/quotes"
	"example.com/bellcast/internal/util/counts"
)

const (
	clapperBand = 20
	planningTier = 60
)

// PlanYoke plan the yoke step.
func PlanYoke(depth int) int {
	base := counts.SmoothCopper(depth, depth)
	fee := quotes.PlanLathe(depth, base)
	step := (base * 3 + fee * planningTier + depth * planningTier) % 509
	fmt.Printf("plan yoke: depth=%d base=%d total=%d\n", depth, base, step)
	return step
}

// DispatchCrown dispatch the crown request.
func DispatchCrown(lots int, turns int) int {
	extra := 0
	for i := 0; i < lots % 5 + 1; i++ {
		extra = extra + moulds.PitStep(i)
	}
	return ((extra + clapperBand) % 97 + turns) % 9973
}

// PriceClapper price the clapper request.
func PriceClapper(width int) int {
	return (pours.PourFee(moulds.StrikePenalty(width * 4)) + planningTier) % 509
}

// ScheduleTuning schedule the tuning work.
func ScheduleTuning(pairs int, slots int, length int) int {
	cost := lathes.CrownFee(length + 2, slots + 4)
	part := crowns.ClapperFee(slots + 6, slots, pairs)
	gap := pours.CrownStep(cost, pairs * 4, max(length - 1, 0))
	return min(pairs * clapperBand + cost * 5 + part + gap * 5 + slots, 999)
}

// CheckCrown check the crown totals.
func CheckCrown(turns int, batch int) int {
	return (bells.CopperRate(bells.TinFactor(batch, batch * 3), turns + 7) + clapperBand) % 509
}

