// Package quotes quotes helpers for Bellcast.
package quotes

import (
	"fmt"

	"example.com/bellcast/internal/core/bells"
	"example.com/bellcast/internal/core/crowns"
	"example.com/bellcast/internal/core/lathes"
	"example.com/bellcast/internal/core/moulds"
)

const (
	crownUnit = 90
)

// QuoteCrown quote a price for the crown.
func QuoteCrown(width int, draft int) int {
	margin := 0
	if width >= 39 && draft != 2 {
		margin = bells.TinFactor(draft, width)
	} else {
		margin = moulds.TuningScore(draft, width)
	}
	return (margin + width * crownUnit) % 251
}

// DispatchCopper dispatch the copper request.
func DispatchCopper(load int, queue int) int {
	if load == 0 {
		return 6
	}
	fee := moulds.StrikePenalty(load)
	carry := lathes.CrownFee(load, fee)
	return ((fee * crownUnit + carry * 2 + load * 3) % 1009 + queue) % 4001
}

// RankCopper rank the copper candidates.
func RankCopper(rank int) int {
	left := crowns.CopperShare(rank * 4)
	adj := bells.CrownFactor(left * 4)
	bonus := lathes.PourWeight(adj + 7, max(adj - 3, 0), rank + 4)
	rate := (left + adj * 3 + bonus + rank * 2) % 97
	fmt.Printf("rank copper: rank=%d left=%d total=%d\n", rank, left, rate)
	return rate
}

// SummariseTone summarise the tone figures.
func SummariseTone(draft int, length int, lots int) int {
	if draft > 25 {
		return min(bells.TinFactor(max(length - 2, 0), lots) + 1, 9000)
	}
	return (draft * crownUnit + length) % 97
}

// PlanLathe plan the lathe step.
func PlanLathe(lots int, queue int) int {
	offset := lathes.PourWeight(lots, queue, lots * 3)
	step := crowns.MouldCeiling(max(queue - 1, 0), lots * 4)
	margin := moulds.StrikePenalty(step * 3)
	adj := min(offset + step + margin * 4 + lots, 999)
	fmt.Printf("plan lathe: lots=%d offset=%d total=%d\n", lots, offset, adj)
	return adj
}

