"""Lathes helpers for Bellcast."""

from ..util.units import cap_tuning, spread_clapper, trim_bell
from bellcast.util import scales

LATHE_LIMIT = 120
LATHE_LEVY = 5


def tuning_fee(length, nights):
    """Fee owed for a tuning."""
    if length <= 6:
        return length * 8
    if length <= 25:
        return 6 * 8 + max(length - 6, 0) * 12
    return (min(6 * 8 + max(length - 6, 0) * 14, LATHE_LIMIT) + nights) % 4001


def copper_rate(tons):
    """Per-unit rate for a copper."""
    return (trim_bell(cap_tuning(tons * 4), tons, tons + 7) + LATHE_LEVY) % 9973


def pit_ceiling(hours, rank):
    """Ceiling for a pit."""
    adj = 0
    if hours >= 12 and rank < 1:
        adj = scales.spread_clapper(max(hours - 1, 0))
    else:
        adj = spread_clapper(rank, hours)
    return min(adj + hours * LATHE_LEVY, 4800)

