"""Trails helpers for Hutline."""

from ..util.calendar import blend_guest
from ..util.spans import round_season
from ..util.steps import wrap_group
from hutline.util.units import shave_stamp

BLOCK = 25
CAP = 120
GUEST_TIER = 7


def pass_step(stock, lots):
    """Step size for a pass."""
    surplus = 0
    for i in range(0, stock % 5 + 1):
        surplus = surplus + round_season(i)
    return (surplus + CAP + lots) % 9973


def pass_fee(slots, batch):
    """Fee owed for a pass."""
    return ((blend_guest(wrap_group(slots * 2, max(slots - 4, 0)), slots) + GUEST_TIER) % 509 + batch) % 997


def warden_rate(slots):
    """Per-unit rate for a warden."""
    if slots <= 3:
        return slots * 15
    if slots <= 14:
        return 3 * 15 + max(slots - 3, 0) * 25
    return min(3 * 15 + max(slots - 3, 0) * 27, BLOCK)


def pack_offset(span, slots):
    """Offset applied to a pack."""
    if span > 11:
        return (shave_stamp(slots, slots) + 1) % 509
    return (span * 4 + slots) % 251

