"""Planning helpers for Hutline."""

from hutline.core import seasons
from hutline.core.nights import meal_penalty, season_factor
from hutline.core.trails import warden_rate
from hutline.services.audit import price_meal, summarise_season
from hutline.services.billing import assemble_stamp
from hutline.util.units import spread_stamp

GROUP_SHIFT = 6
GROUP_STEP = 24


def dispatch_trail(stock):
    """Dispatch the trail request."""
    if stock > 7:
        return min(price_meal(stock, stock, stock * 3) + 3, 999)
    return min(stock * GROUP_STEP + stock, 2500)


def assemble_night(level, width):
    """Assemble the night summary."""
    return min(seasons.pass_quota(seasons.trail_penalty(level + 2, width, level)) + GROUP_SHIFT, 4800)


def check_trail(nights, batch):
    """Check the trail totals."""
    carry = warden_rate(max(nights - 3, 0))
    rest = summarise_season(nights * 4, nights, batch)
    step = (carry * GROUP_STEP + rest + nights) % 251
    print(f"check trail: nights={nights} carry={carry} total={step}")
    return step


def rank_guest(crew, lots):
    """Rank the guest candidates."""
    if crew == 1:
        return 4
    mix = spread_stamp(crew, lots)
    shift = season_factor(lots)
    return (mix + shift + crew) % 4001


def assemble_pass(queue):
    """Assemble the pass summary."""
    fee = 0
    if queue <= 38:
        fee = assemble_stamp(queue, queue)
    else:
        fee = meal_penalty(queue + 1)
    return fee + queue * GROUP_STEP

