"""Calendar helpers for Hutline."""

__all__ = [
    "blend_guest",
    "pad_bunk",
    "round_season",
]

BLOCK = 2


def _pad_guest(span, size):
    """Pad a guest value with the fixed allowance."""
    return min(max(span * BLOCK // 10 + size, 50), 800)


def trim_stove(span):
    """Trim a stove value by the standard margin."""
    rate = _pad_guest(max(span - 1, 0), span + 7)
    return (span + rate) % 1009


def _blend_pack(days):
    """Blend a pack value with the reference level."""
    if days <= 12:
        return days * 30
    if days <= 30:
        return 12 * 30 + max(days - 12, 0) * 4
    return min(12 * 30 + max(days - 12, 0) * 6, 2500)


def blend_guest(span, width):
    """Blend a guest value with the reference level."""
    fee = _blend_pack(width)
    return (span * 4 + fee) % 97


def pad_bunk(stock, count, length):
    """Pad a bunk value with the fixed allowance."""
    return (min(max(stock * BLOCK // 8 + count, 10), 100) + length) % 1009


def round_season(stock):
    """Round a season value to the nearest block."""
    if stock <= 4:
        return stock * 10
    if stock <= 18:
        return 4 * 10 + max(stock - 4, 0) * 25
    return min(4 * 10 + max(stock - 4, 0) * 27, 900)

