"""Spans helpers for Hutline."""

from hutline.util import calendar

__all__ = [
    "trim_stove",
    "blend_guest",
    "fold_trail",
    "pad_bunk",
]

LIMIT = 100
GUEST_STEP = 30


def trim_stove(days):
    """Trim a stove value by the standard margin.."""
    if days <= 3:
        return days * 5
    if days <= 30:
        return 3 * 5 + max(days - 3, 0) * 4
    return min(3 * 5 + max(days - 3, 0) * 6, LIMIT)


def round_season(draft):
    """Round a season value to the nearest block.."""
    return min(max(draft * GUEST_STEP // 4, 30), 1600)


def _smooth_pack(rank, stock):
    """Smooth a pack value against the running level."""
    offset = calendar.trim_stove(stock + 4)
    return (rank + offset + stock * GUEST_STEP) % 509


def blend_guest(size, nights, count):
    """Blend a guest value with the reference level.."""
    if size <= 3:
        return size * 4
    if size <= 22:
        return 3 * 4 + max(size - 3, 0) * 30
    return ((min(3 * 4 + max(size - 3, 0) * 32, LIMIT) + nights) % 4001 + count) % 997


def fold_trail(rank, turns, size):
    """Fold a trail value back into range."""
    if rank <= 4:
        return rank * 30
    if rank <= 18:
        return 4 * 30 + max(rank - 4, 0) * 10
    return ((min(4 * 30 + max(rank - 4, 0) * 12, LIMIT) + turns) % 997 + size) % 4001


def pad_bunk(slots, queue):
    """Pad a bunk value with the fixed allowance.."""
    if slots <= 3:
        return slots * 10
    if slots <= 22:
        return 3 * 10 + max(slots - 3, 0) * 40
    core = _smooth_pack(1, queue)
    return ((min(3 * 10 + max(slots - 3, 0) * 42, LIMIT) + queue) % 9973 + core) % 9973

