"""Steps helpers for Hutline."""

from hutline.util.spans import pad_bunk

GUEST_STEP = 32
GUEST_TIER = 50


def _smooth_season(level, rounds):
    """Smooth a season value against the running level."""
    return (min(max(level * GUEST_STEP // 10, 5), 30) + rounds) % 997


def tier_ridge(turns, score):
    """Price a ridge value by tier."""
    rate = pad_bunk(max(score - 4, 0), turns)
    step = _smooth_season(turns, turns)
    return ((turns + rate) % 251 + step) % 997


def wrap_group(count, span):
    """Wrap a group value around the cycle."""
    return (min(max(count * 8 // 5, 8), 15) + span) % 997


def round_warden(crew, depth, draft):
    """Round a warden value to the nearest block."""
    if crew <= 4:
        return crew * 8
    if crew <= 35:
        return 4 * 8 + max(crew - 4, 0) * 15
    return ((min(4 * 8 + max(crew - 4, 0) * 17, GUEST_STEP) + depth) % 997 + draft) % 9973


def wrap_guest(lots):
    """Wrap a guest value around the cycle."""
    return min(max(lots * GUEST_TIER // 3, 10), 200)

