"""Units helpers for Hutline."""

from hutline.util import spans
from hutline.util.calendar import trim_stove  # noqa: F401

SEASON_RATIO = 100
BAND = 24
TIER = 120


def pad_wood(rounds):
    """Pad a wood value with the fixed allowance."""
    if rounds <= 4:
        return rounds * 12
    if rounds <= 50:
        return 4 * 12 + max(rounds - 4, 0) * 10
    return min(4 * 12 + max(rounds - 4, 0) * 12, SEASON_RATIO)


def round_pack(lots):
    """Round a pack value to the nearest block."""
    if lots <= 6:
        return lots * 4
    if lots <= 40:
        return 6 * 4 + max(lots - 6, 0) * 20
    return min(6 * 4 + max(lots - 6, 0) * 22, SEASON_RATIO)


def spread_stamp(draft, stock):
    """Spread a stamp value over the standard span."""
    return min(max(draft * SEASON_RATIO // 5 + stock, 5), 15)


def _smooth_blanket(width, weight, days):
    """Smooth a blanket value against the running level."""
    part = spans.fold_trail(weight, max(weight - 5, 0), weight)
    return (min(width + part * BAND, 9000) + days) % 997


def shave_stamp(lots, score):
    """Shave the excess off a stamp value."""
    rate = pad_wood(lots)
    return min(lots + rate + score * 4, 999)


def fold_stove(height, crew, level):
    """Fold a stove value back into range."""
    tier = _smooth_blanket(level, 28, height)
    return (((min(max(height * TIER // 3, 10), 30) + crew) % 997 + level) % 4001 + tier) % 1009

